func (s *Supplier) downloadSeriesSubHDItemWithRetry(browser *rod.Browser, item HdListItem, topN int64) (*supplier.SubInfo, error) {
	return retrySeriesSubHDDownload(s.log, s.GetSupplierName(), item.Url, func() (*supplier.SubInfo, error) {
		return s.fileDownloader.GetEx(s.GetSupplierName(), browser, item.Url, topN, item.Season, item.Episode, s.DownFile)
	})
}

func retrySeriesSubHDDownload(log *logrus.Logger, supplierName string, itemURL string, fetch func() (*supplier.SubInfo, error)) (*supplier.SubInfo, error) {
	var subInfo *supplier.SubInfo
	var err error
	for attempt := 1; attempt <= subHDPageRetryAttempts; attempt++ {
		subInfo, err = fetch()
		if err == nil {
			return subInfo, nil
		}
		if shouldRetryPageFetch(err) == false || attempt == subHDPageRetryAttempts {
			return nil, err
		}
		log.Warningln(supplierName, "GetEx transient failure, retry", attempt, itemURL, err)
		time.Sleep(subHDPageRetryDelay)
	}
	return subInfo, err
}

