func (s *Supplier) step0(browser *rod.Browser, keyword string, titleCandidates []string, targetSeason int, targetYear int) ([]string, error) {
	var err error
	defer func() {
		if err != nil {
			notify_center.Notify.Add("subhd_step0", err.Error())
		}
	}()

	rootURL := s.rootURL()
	searchURL := fmt.Sprintf(rootURL+common.SubSubHDSearchUrl, url.QueryEscape(keyword))
	result, err := s.httpGetPage(searchURL)
	if err == nil {
		searchResults, subCount, parseErr := parseSearchResults(result)
		if parseErr == nil {
			return finalizeSubHDSearchResults(s.log, keyword, titleCandidates, targetSeason, targetYear, searchResults, subCount)
		}
		s.log.Warningln("subhd step0 parse failed", "keyword", keyword, "len", len(result))
		if browser == nil {
			return nil, wrapReason(ReasonSearchLayoutChanged, parseErr)
		}
		s.log.Warningln("subhd step0 parse failed, retry with browser", keyword, parseErr)
	} else if browser == nil {
		return nil, wrapReason(ReasonProbeFailed, err)
	} else {
		s.log.Warningln("subhd step0 http fetch failed, retry with browser", keyword, err)
	}

	result, err = s.browserGetPage(browser, searchURL)
	if err != nil {
		return nil, wrapReason(ReasonProbeFailed, err)
	}
	searchResults, subCount, err := parseSearchResults(result)
	if err != nil {
		s.log.Warningln("subhd step0 browser parse failed", "keyword", keyword, "len", len(result))
		return nil, wrapReason(ReasonSearchLayoutChanged, err)
	}
	return finalizeSubHDSearchResults(s.log, keyword, titleCandidates, targetSeason, targetYear, searchResults, subCount)
}

func (s *Supplier) step1(browser *rod.Browser, detailPageUrl string, isMovieOrSeries bool) ([]HdListItem, error) {
	var err error
	defer func() {
		if err != nil {
			notify_center.Notify.Add("subhd_step1", err.Error())
		}
	}()
	rootURL := s.rootURL()
	detailPageUrl = pkg.AddBaseUrl(rootURL, detailPageUrl)
	result, err := s.httpGetPage(detailPageUrl)
	if err == nil {
		lists, parseErr := parseSubtitleRows(result, rootURL, detailPageUrl, isMovieOrSeries, settings.Get().AdvancedSettings.Topic)
		if parseErr == nil {
			return lists, nil
		}
		if browser == nil {
			return nil, wrapReason(ReasonDetailLayoutChanged, parseErr)
		}
		s.log.Warningln("subhd step1 parse failed, retry with browser", detailPageUrl, parseErr)
	} else if browser == nil {
		return nil, wrapReason(ReasonProbeFailed, err)
	} else {
		s.log.Warningln("subhd step1 http fetch failed, retry with browser", detailPageUrl, err)
	}

	result, err = s.browserGetPage(browser, detailPageUrl)
	if err != nil {
		return nil, wrapReason(ReasonProbeFailed, err)
	}
	lists, err := parseSubtitleRows(result, rootURL, detailPageUrl, isMovieOrSeries, settings.Get().AdvancedSettings.Topic)
	if err != nil {
		return nil, wrapReason(ReasonDetailLayoutChanged, err)
	}

	return lists, nil
}

