func (s *Supplier) ensureBrowser(browser *rod.Browser) (*rod.Browser, error) {
	if browser != nil {
		return browser, nil
	}
	return rod_helper.NewBrowserEx(rod_helper.NewBrowserOptions(s.log, true, settings.Get()))
}

func (s *Supplier) browserGetPage(browser *rod.Browser, pageURL string) (string, error) {
	if browser == nil {
		return "", errors.New("browser is nil")
	}
	pageHTML, page, err := rod_helper.HttpGetFromBrowser(browser, pageURL, s.tt)
	if page != nil {
		_ = page.Close()
	}
	if err != nil {
		return "", err
	}
	return pageHTML, nil
}

func shouldRetrySubHDDetailPageWithBrowser(err error) bool {
	switch reasonOf(err) {
	case ReasonDetailLayoutChanged, ReasonProbeFailed:
		return true
	default:
		return false
	}
}

func shouldRetrySubHDSearchPageWithBrowser(err error) bool {
	switch reasonOf(err) {
	case ReasonSearchLayoutChanged, ReasonProbeFailed:
		return true
	default:
		return false
	}
}

func shouldContinueSeriesKeywordSearch(err error) bool {
	switch reasonOf(err) {
	case ReasonSearchLayoutChanged, ReasonProbeFailed:
		return true
	default:
		return false
	}
}

